#!/usr/bin/env python3
"""Independent naive reference for PROTOCOL.md v3 (development only).

Deliberately straightforward: recomputes everything per query with simple
loops, brute-force or NetworkX planning.  Used only to cross-check the
submission on generated campaigns.  Not copied from the submission code.
"""
import base64
import binascii
import io
import ipaddress
import json
import re
import struct
import csv
import hashlib

DOC = ipaddress.IPv6Network('2001:db8::/32')
COLUMNS = ['type','id','revision','published','op','lease','event','probe',
           'target','responder','result','service','attempt','payload']

def a2i(s):
    return int(ipaddress.IPv6Address(s))

def i2a(n):
    return str(ipaddress.IPv6Address(n))

def manifest_of(job):
    out = []
    lows = {}
    for lid in sorted(job, key=lambda k: k['id']):
        pass
    return out

def build_manifest(job):
    entries = []
    low = {}
    for lease in sorted(job['leases'], key=lambda r: r['id']):
        net = ipaddress.IPv6Network(lease['prefix'], strict=True)
        lid = lease['id']
        low[lid] = set()
        for subnet in sorted(lease['subnets']):
            base = int(net.network_address) + (subnet << 64)
            canon = str(ipaddress.IPv6Network((base, 64)))
            material = f"{job['seed']}\n{lid}\n{canon}".encode()
            iid = int.from_bytes(hashlib.sha256(material).digest()[:8], 'big') | (1 << 63)
            canary = base + iid
            entries.append({'lease': lid, 'probe': f'{subnet}/c', 'target': i2a(canary)})
            for n in range(1, lease['low_count'] + 1):
                entries.append({'lease': lid, 'probe': f'{subnet}/i{n}', 'target': i2a(base + n)})
                low[lid].add(base + n)
    return entries, low

def parse_row(v, leases, services, manifest_map):
    """Independent record validation; returns ('ok', rec) or raises BadRow."""
    if len(v) != 14:
        raise BadRow()
    t, rid, rev, pub, op, lease, event, probe, target, responder, result, service, attempt, payload = v
    if t not in ('icmp', 'app'):
        raise BadRow()
    if not re.fullmatch(r'[A-Za-z0-9_-]{1,24}', rid):
        raise BadRow()
    if not re.fullmatch(r'[0-9]{1,16}', rev) or int(rev) > 10**9:
        raise BadRow()
    if not re.fullmatch(r'[0-9]{1,16}', pub) or int(pub) > 10**12:
        raise BadRow()
    rev, pub = int(rev), int(pub)
    if op == 'delete':
        if any(x != '' for x in v[5:]):
            raise BadRow()
        return {'identity': (t, rid), 'type': t, 'revision': rev, 'published': pub,
                'op': 'delete'}
    if op != 'put':
        raise BadRow()
    if lease not in leases:
        raise BadRow()
    if not re.fullmatch(r'[0-9]{1,16}', event):
        raise BadRow()
    ev = int(event)
    if not (leases[lease]['start'] <= ev < leases[lease]['end']):
        raise BadRow()
    if ev > pub:
        raise BadRow()
    try:
        tgt = a2i(target)
        if not (int(DOC.network_address) <= tgt <= int(DOC.broadcast_address)):
            raise BadRow()
    except ValueError:
        raise BadRow()
    canary = False
    if t == 'icmp':
        key = (lease, probe)
        if key not in manifest_map or manifest_map[key][0] != tgt:
            raise BadRow()
        canary = manifest_map[key][1]
        if result not in ('echo', 'error', 'timeout'):
            raise BadRow()
        if result == 'timeout':
            if responder != '':
                raise BadRow()
            resp = None
        else:
            try:
                resp = a2i(responder)
                if not (int(DOC.network_address) <= resp <= int(DOC.broadcast_address)):
                    raise BadRow()
            except ValueError:
                raise BadRow()
        if service != '' or attempt != '' or payload != '':
            raise BadRow()
    else:
        if probe != '' or responder != '':
            raise BadRow()
        if service not in services:
            raise BadRow()
        if not re.fullmatch(r'[0-9]{1,16}', attempt) or int(attempt) > 10**6:
            raise BadRow()
        att = int(attempt)
        if result not in ('open', 'closed', 'timeout'):
            raise BadRow()
        try:
            body = base64.b64decode(payload.encode('ascii'), validate=True)
        except (ValueError, UnicodeError, binascii.Error):
            raise BadRow()
        if len(body) > 65536:
            raise BadRow()
        if result != 'open' and len(body) != 0:
            raise BadRow()
        if services[service] == 'tcp' and len(body) != 0:
            raise BadRow()
    rec = {'identity': (t, rid), 'type': t, 'revision': rev, 'published': pub,
           'op': 'put', 'lease': lease, 'event': ev, 'probe': probe,
           'target': tgt, 'responder': resp if t == 'icmp' else None,
           'result': result, 'service': service if t == 'app' else None,
           'attempt': att if t == 'app' else None,
           'payload': body if t == 'app' else b'', 'canary': canary}
    rec['content'] = ('delete' if op == 'delete' else
                      (rec['lease'], rec['event'], rec['probe'], rec['target'],
                       rec['responder'], rec['result'], rec['service'],
                       rec['attempt'], rec['payload']))
    return rec

class BadRow(Exception):
    pass

def read_captures(job):
    """Decode capture list the simple way; returns (records, rejected)."""
    records, rejected = [], []
    for ci, cap in enumerate(job['captures']):
        data = b''.join(base64.b64decode(c.encode('ascii'), validate=True)
                        for c in cap['chunks'])
        if cap['encoding'] == 'zstd':
            import zstandard as zstd
            data = zstd.ZstdDecompressor().decompress(data, read_across_frames=True)
        text = io.TextIOWrapper(io.BytesIO(data), encoding='utf-8', newline='')
        rows = csv.reader(text, strict=True)
        header = next(rows, None)
        assert header == COLUMNS, ('header', header)
        leases = {r['id']: r for r in job['leases']}
        services = {r['id']: r['kind'] for r in job['services']}
        m, _ = build_manifest(job)
        mmap = {(e['lease'], e['probe']): (a2i(e['target']), e['probe'].endswith('/c'))
                for e in m}
        for oi, v in enumerate(rows):
            try:
                records.append(parse_row(v, leases, services, mmap))
            except BadRow:
                rejected.append([ci, oi])
    return records, rejected

def winners_at(records, q):
    """Reconcile identities visible at q; returns (live rows, counts)."""
    per = {}
    for r in records:
        if r['published'] > q:
            continue
        key = r['identity']
        cur = per.get(key)
        if cur is None:
            per[key] = [r['revision'], {r['content']: r}]
        elif r['revision'] > cur[0]:
            per[key] = [r['revision'], {r['content']: r}]
        elif r['revision'] == cur[0]:
            cur[1].setdefault(r['content'], r)
    live, counts = [], {'live': 0, 'deleted': 0, 'conflict': 0}
    for rev, contents in per.values():
        if len(contents) > 1:
            counts['conflict'] += 1
        else:
            rec = next(iter(contents.values()))
            if rec['op'] == 'delete':
                counts['deleted'] += 1
            else:
                counts['live'] += 1
                live.append(rec)
    return live, counts

def sig_ref(kind, data):
    """Independent open-signature parsing."""
    try:
        if kind == 'tcp':
            return ('tcp',) if data == b'' else None
        if kind == 'adb':
            if not 24 <= len(data) <= 24 + 65535:
                return None
            cmd, a0, a1, ln, ck, mg = struct.unpack('<6I', data[:24])
            if cmd ^ mg != 0xffffffff or ln > 65535 or len(data) != 24 + ln:
                return None
            body = data[24:]
            if sum(body) & 0xffffffff != ck:
                return None
            if cmd == 0x4e584e43:
                ver = '%d.%d.%d' % ((a0 >> 16) & 255, (a0 >> 8) & 255, a0 & 255)
                return ('CNXN', ver, body.decode('utf-8'))
            if cmd == 0x48545541:
                return ('AUTH', a0, a1, bytes(body))
            return None
        # sync
        import plistlib
        pos = 0
        vals = []
        want = ['ProductVersion', 'ProductName']
        for w in want:
            if len(data) - pos < 4:
                return None
            ln = int.from_bytes(data[pos:pos+4], 'big')
            pos += 4
            if not 1 <= ln <= 65532 or len(data) - pos < ln:
                return None
            body = data[pos:pos+ln]
            pos += ln
            obj = plistlib.loads(body)
            if type(obj) is not dict or set(obj) != {'Key', 'Request', 'Value'}:
                return None
            if obj['Key'] != w or obj['Request'] != 'GetValue':
                return None
            if type(obj['Value']) is not str or not obj['Value']:
                return None
            vals.append(obj['Value'])
        if pos != len(data):
            return None
        return ('sync', vals[0], vals[1])
    except Exception:
        return None

def run(job):
    entries, low = build_manifest(job)
    records, rejected = read_captures(job)
    leases = {r['id']: r for r in job['leases']}
    services = {r['id']: r['kind'] for r in job['services']}
    queries = sorted(job['queries'])
    snapshots = []
    analyses = {}
    for q in queries:
        live, counts = winners_at(records, q)
        an = {}
        unbound = 0
        for lid in sorted(leases):
            lease = leases[lid]
            internal, external, wit, alias = set(), set(), {}, False
            for r in live:
                if r['op'] != 'put' or r['type'] != 'icmp' or r['lease'] != lid:
                    continue
                if r['canary']:
                    if r['result'] == 'echo' and r['responder'] == r['target']:
                        alias = True
                    continue
                if r['result'] == 'echo' and r['responder'] == r['target']:
                    internal.add(r['responder'])
                    k = ('I', r['responder'])
                elif r['result'] != 'timeout' and r['responder'] != r['target']:
                    external.add(r['responder'])
                    k = ('E', r['responder'])
                else:
                    continue
                if k not in wit or r['event'] < wit[k]:
                    wit[k] = r['event']
            conflicts = internal & external
            active = lease['start'] <= q < lease['end']
            if not active:
                state = 'inactive'
            elif alias:
                state = 'alias'
            elif conflicts:
                state = 'conflict'
            else:
                state = 'usable'
            ci = internal if state == 'usable' else set()
            ce = external if state == 'usable' else set()
            if active:
                unresolved = set(low[lid]) - ci - ce
                show_conf = set(conflicts)
            else:
                unresolved = set()
                show_conf = set()
            status, errors = {}, {s: 0 for s in services}
            groups = {}
            for r in live:
                if r['op'] != 'put' or r['type'] != 'app' or r['lease'] != lid:
                    continue
                if state == 'usable':
                    role = ('I' if r['target'] in internal else
                            'E' if r['target'] in external else None)
                    if role is not None and wit.get((role, r['target']), 10**20) <= r['event']:
                        groups.setdefault((r['target'], r['service']), []).append(r)
                        continue
                unbound += 1
            for (tgt, sid), grows in groups.items():
                mx = max(r['attempt'] for r in grows)
                top = [r for r in grows if r['attempt'] == mx]
                sigs = [sig_ref(services[sid], r['payload']) if r['result'] == 'open' else None
                        for r in top]
                bad = sum(1 for s, r in zip(sigs, top) if r['result'] == 'open' and s is None)
                errors[sid] += bad
                if all(r['result'] == 'closed' for r in top):
                    status[(tgt, sid)] = 'closed'
                elif all(r['result'] == 'open' for r in top) and bad == 0 and len(set(sigs)) == 1:
                    status[(tgt, sid)] = 'open'
                else:
                    status[(tgt, sid)] = 'unknown'
            an[lid] = dict(state=state, conflicts=show_conf, internal=ci, external=ce,
                           unresolved=unresolved, status=status, errors=errors)
        svcs_out = []
        leases_out = []
        for lid in sorted(leases):
            e = an[lid]
            sarr = []
            for sid in sorted(services):
                st = e['status']
                io_ = sorted((a for a in e['internal'] if st.get((a, sid)) == 'open'), reverse=True)
                io_ = [i2a(a) for a in sorted((a for a in e['internal'] if st.get((a, sid)) == 'open'))]
                ic_ = [i2a(a) for a in sorted((a for a in e['internal'] if st.get((a, sid)) == 'closed'))]
                eo = [i2a(a) for a in sorted((a for a in e['external'] if st.get((a, sid)) == 'open'))]
                ec = [i2a(a) for a in sorted((a for a in e['external'] if st.get((a, sid)) == 'closed'))]
                ext = e['external']
                ionly = io_ if (ext and all(st.get((a, sid)) == 'closed' for a in ext)) else []
                sarr.append({'id': sid, 'internal_open': io_, 'internal_closed': ic_,
                             'external_open': eo, 'external_closed': ec,
                             'internal_only': ionly, 'protocol_errors': e['errors'].get(sid, 0)})
            leases_out.append({'lease': lid, 'state': e['state'],
                               'conflicts': [i2a(a) for a in sorted(e['conflicts'])],
                               'internal': [i2a(a) for a in sorted(e['internal'])],
                               'external': [i2a(a) for a in sorted(e['external'])],
                               'unresolved': [i2a(a) for a in sorted(e['unresolved'])],
                               'services': sarr})
        snapshots.append({'at': q, 'ledger': counts, 'unbound_applications': unbound,
                          'leases': leases_out})
        analyses[q] = an
    active = {}
    for r in job['requests']:
        q = r['at']
        e = analyses[q][r['lease']]
        tgt = a2i(r['target'])
        ok = e['state'] == 'usable' and tgt in e['internal']
        active[r['id']] = bool(ok and e['status'].get((tgt, r['service']), 'unknown') == 'unknown')

    # ---- planning: NetworkX min-cost max-flow on the same constraints ----
    import networkx as nx
    G = nx.DiGraph()
    SRC, SNK = '@src', '@snk'
    cap_sum = {}
    def charge(group, paths, tree, amount):
        for n in paths[group]:
            cap_sum[('rq' if tree == 'rq' else 'oq', n)] = 0
    for row in job['request_quotas']:
        cap_sum[('rq', row['id'])] = row['capacity']
    for row in job['offer_quotas']:
        cap_sum[('oq', row['id'])] = row['capacity']
    rqpaths = {}
    for row in job['request_quotas']:
        chain, at = [], row['id']
        while at is not None:
            chain.append(at)
            at = {x['id']: x['parent'] for x in job['request_quotas']}[at]
        rqpaths[row['id']] = chain
    oqpaths = {}
    for row in job['offer_quotas']:
        chain, at = [], row['id']
        while at is not None:
            chain.append(at)
            at = {x['id']: x['parent'] for x in job['offer_quotas']}[at]
        oqpaths[row['id']] = chain
    # request side: source -> group chain caps
    for row in job['request_quotas']:
        G.add_node(('rq', row['id']))
    def add_edge(u, v, cap, cost):
        G.add_edge(u, v, capacity=cap, weight=cost)
    for row in job['request_quotas']:
        if row['parent'] is None:
            add_edge(SRC, ('rq', row['id']), row['capacity'], 0)
        else:
            add_edge(('rq', row['parent']), ('rq', row['id']), row['capacity'], 0)
    for r in job['requests']:
        add_edge(('rq', r['group']), ('r', r['id']), 1, 0)
    pairs = []
    for off in job['offers']:
        net = ipaddress.IPv6Network(off['prefix'], strict=True)
        for rid in off['requests']:
            req = next(x for x in job['requests'] if x['id'] == rid)
            if not active[rid]:
                continue
            if req['service'] != off['service']:
                continue
            if not (req['at'] <= off['time'] < leases[req['lease']]['end']):
                continue
            if a2i(req['target']) not in net:
                continue
            pairs.append((rid, off['id']))
            add_edge(('r', rid), ('o', off['id']), 1, off['cost'])
    for off in job['offers']:
        add_edge(('o', off['id']), ('oq', off['group']), off['capacity'], 0)
    for row in job['offer_quotas']:
        if row['parent'] is None:
            add_edge(('oq', row['id']), SNK, row['capacity'], 0)
        else:
            add_edge(('oq', row['id']), ('oq', row['parent']), row['capacity'], 0)
    for n in list(G.nodes):
        G.add_edge(n, SNK, capacity=0, weight=0) if False else None
    # demands for min-cost flow
    demand = {n: 0 for n in G.nodes}
    demand[SRC] = 4096
    demand[SNK] = -4096
    for n in G.nodes:
        if n not in demand:
            demand[n] = 0
    G.add_node(SRC); G.add_node(SNK)
    H = nx.DiGraph(G)
    # use max-flow value first (network_simplex needs balanced supplies)
    # Balance: source supplies flow equal to max flow value; compute via max flow.
    H.add_node(SRC, demand=-10**9)
    # simpler: min_cost_flow with huge supply/demand then look at used pair edges?
    # network_simplex needs balanced; instead run max-flow-min-cost with supersink trick:
    # give SRC demand = -M, SNK demand = +M with M large; leftover absorbs at...
    # Not valid. Use: compute max flow value with maximum_flow, then set demands.
    MF = nx.maximum_flow(G, SRC, SNK)
    value = MF[0]
    for n in G.nodes:
        G.nodes[n]['demand'] = 0
    G.nodes[SRC]['demand'] = -value
    G.nodes[SNK]['demand'] = value
    flow = nx.min_cost_flow(G, demand=0, capacity='capacity', weight='weight')
    amount = 0
    spend = 0
    for rid, oid in pairs:
        f = flow.get(('r', rid), {}).get(('o', oid), 0)
        if f:
            amount += 1
            spend += next(x['cost'] for x in job['offers'] if x['id'] == oid)
    out = {'manifest': entries, 'rejected': rejected, 'snapshots': snapshots,
           'active_requests': [{'id': k, 'active': active[k]} for k in sorted(active)],
           'plan': {'resolved': amount, 'cost': spend, 'assignments': []}}
    return out
